-- join_order_sem_test.sql — Figure-1 P4 (ADR-0026): semantic-operator placement in the planner.
-- Asserts the C port (src/planner/join_order_sem.c) returns EXACTLY the values of the Python
-- spec (src/planner/join_order_sem_ref.py): hand-computed cases, a pinned grid (expected values
-- generated by the ref; float8 compared with =, i.e. bit-for-bit), and every validation error.
-- Also checks the frozen 0.1.0 surface is untouched. Runs under psql -v ON_ERROR_STOP=1 on
-- stock PG 16/17 (STOCK_TESTS) and via scripts/join_order_sem_test.sh.

CREATE EXTENSION IF NOT EXISTS join_order;

-- (0) Frozen core unchanged.
DO $$
BEGIN
    ASSERT tridb_choose_join_order(50, 100000) = 'filter_first', 'frozen: selective -> filter_first';
    ASSERT tridb_choose_join_order(90000, 100000) = 'vector_first', 'frozen: broad -> vector_first';
    RAISE NOTICE 'PASS P4: frozen join_order surface unchanged';
END $$;

-- (1) Hand-computed ordering + cost.
DO $$
BEGIN
    -- equal sel: cheap first; equal cost: selective first.
    ASSERT tridb_place_sem('{0.5,0.5,0.5}', '{10,1,5}', '{0,0,0}') = '{1,2,0}', 'cheap first';
    ASSERT tridb_place_sem('{0.9,0.1,0.5}', '{1,1,1}', '{0,0,0}') = '{1,2,0}', 'selective first';
    -- rank0 = 0.9/100, rank1 = 0.1/1 -> the cheap weak filter goes first.
    ASSERT tridb_place_sem('{0.1,0.9}', '{100,1}', '{0,0}') = '{1,0}', 'rank tradeoff';
    -- c_eff == 0 -> +inf rank, even at sel 1 (zero cost, or fully cached with cache_cost 0).
    ASSERT tridb_place_sem('{0.01,1.0,0.5}', '{1,0,7}', '{0,0,1}') = '{1,2,0}', 'free first';
    -- a nonzero cache_cost keeps a fully cached predicate from being free.
    ASSERT tridb_place_sem('{0.5,0.2}', '{10,1}', '{1,0}', 5.0) = '{1,0}', 'cache_cost';
    -- stable ties.
    ASSERT tridb_place_sem('{0.5,0.5,0.5,0.5}', '{2,2,2,2}', '{0,0,0,0}') = '{0,1,2,3}', 'ties';
    ASSERT tridb_place_sem('{0.5,0.2,0.5}', '{1,3,1}', '{0,0,0}') = '{0,2,1}', 'ties 2';
    -- empty input.
    ASSERT tridb_place_sem('{}', '{}', '{}') = '{}'::int[], 'empty';
    ASSERT tridb_sem_plan_cost('{}', '{}', '{}', '{}', 1000) = 0.0, 'empty cost';
    -- order [0,1]: 100*(4 + 8*0.5) = 800; order [1,0]: 100*(8 + 4*0.25) = 900.
    ASSERT tridb_sem_plan_cost('{0.5,0.25}', '{4,8}', '{0,0}', '{0,1}', 100) = 800.0, 'cost 800';
    ASSERT tridb_sem_plan_cost('{0.5,0.25}', '{4,8}', '{0,0}', '{1,0}', 100) = 900.0, 'cost 900';
    -- c_eff0 = 10*0.5 + 2*0.5 = 6, c_eff1 = 4 -> 10*(6 + 4*0.5) = 80.
    ASSERT tridb_sem_plan_cost('{0.5,0.5}', '{10,4}', '{0.5,0}', '{0,1}', 10, 2.0) = 80.0, 'cost cache';
    -- STRICT: a NULL argument yields NULL.
    ASSERT tridb_place_sem(NULL, '{1}', '{0}') IS NULL, 'strict';
    RAISE NOTICE 'PASS P4: hand-computed tridb_place_sem / tridb_sem_plan_cost';
END $$;

-- (2) Pinned grid: place_sem order + sem_plan_cost(n_in=1000) bit-identical to the Python ref.
CREATE TEMP TABLE sem_grid(id int, sels float8[], costs float8[], hits float8[], cc float8,
                           exp_ord int[], exp_cost float8);
DO $$
DECLARE bad int; total int;
BEGIN
    SELECT count(*) INTO total FROM sem_grid;
    SELECT count(*) INTO bad FROM sem_grid
     WHERE tridb_place_sem(sels, costs, hits, cc) IS DISTINCT FROM exp_ord
        OR tridb_sem_plan_cost(sels, costs, hits, exp_ord, 1000.0, cc) IS DISTINCT FROM exp_cost;
    ASSERT bad = 0, format('%s of %s grid cases differ from join_order_sem_ref.py', bad, total);
    RAISE NOTICE 'PASS P4: % placement grid cases bit-identical to the ref', total;
END $$;

-- (3) tridb_sem_batch grid (expected values from the ref).
CREATE TEMP TABLE sem_batch_grid(k int, sel float8, lo int, hi int, expected int);
DO $$
DECLARE bad int; total int;
BEGIN
    SELECT count(*) INTO total FROM sem_batch_grid;
    SELECT count(*) INTO bad FROM sem_batch_grid
     WHERE tridb_sem_batch(k, sel, lo, hi) IS DISTINCT FROM expected;
    ASSERT bad = 0, format('%s of %s batch cases differ from the ref', bad, total);
    ASSERT tridb_sem_batch(10, 0.3, 1, 1000) = 34, 'ceil(33.3)';
    ASSERT tridb_sem_batch(2147483647, 0.0, 1, 2147483647) = 2147483647, 'no int overflow';
    RAISE NOTICE 'PASS P4: % batch grid cases match the ref', total;
END $$;

-- (4) Validation errors: each call must raise invalid_parameter_value / null_value_not_allowed.
DO $$
DECLARE
    stmt text;
    stmts text[] := ARRAY[
        $q$SELECT tridb_place_sem('{0.5}', '{1,2}', '{0}')$q$,
        $q$SELECT tridb_place_sem('{1.5}', '{1}', '{0}')$q$,
        $q$SELECT tridb_place_sem('{-0.1}', '{1}', '{0}')$q$,
        $q$SELECT tridb_place_sem('{NaN}', '{1}', '{0}')$q$,
        $q$SELECT tridb_place_sem('{0.5}', '{-1}', '{0}')$q$,
        $q$SELECT tridb_place_sem('{0.5}', '{Infinity}', '{0}')$q$,
        $q$SELECT tridb_place_sem('{0.5}', '{1}', '{1.1}')$q$,
        $q$SELECT tridb_place_sem('{0.5}', '{1}', '{0}', -1)$q$,
        $q$SELECT tridb_place_sem('{0.5}', '{1}', '{0}', 'Infinity')$q$,
        $q$SELECT tridb_place_sem('{NULL}', '{1}', '{0}')$q$,
        $q$SELECT tridb_place_sem('{{0.5}}', '{{1}}', '{{0}}')$q$,
        $q$SELECT tridb_place_sem(array_fill(0.5::float8, ARRAY[65]),
                                   array_fill(1::float8, ARRAY[65]),
                                   array_fill(0::float8, ARRAY[65]))$q$,
        $q$SELECT tridb_sem_plan_cost('{0.5,0.5}', '{1,1}', '{0,0}', '{0}', 10)$q$,
        $q$SELECT tridb_sem_plan_cost('{0.5,0.5}', '{1,1}', '{0,0}', '{0,0}', 10)$q$,
        $q$SELECT tridb_sem_plan_cost('{0.5,0.5}', '{1,1}', '{0,0}', '{0,2}', 10)$q$,
        $q$SELECT tridb_sem_plan_cost('{0.5,0.5}', '{1,1}', '{0,0}', '{1,-1}', 10)$q$,
        $q$SELECT tridb_sem_plan_cost('{0.5,0.5}', '{1,1}', '{0,0}', '{0,NULL}', 10)$q$,
        $q$SELECT tridb_sem_plan_cost('{0.5}', '{1}', '{0}', '{0}', -1)$q$,
        $q$SELECT tridb_sem_plan_cost('{0.5}', '{1}', '{0}', '{0}', 'Infinity')$q$,
        $q$SELECT tridb_sem_plan_cost('{0.5}', '{1}', '{0}', '{0}', 'NaN')$q$,
        $q$SELECT tridb_sem_batch(1, 1.5, 1, 10)$q$,
        $q$SELECT tridb_sem_batch(1, 'NaN', 1, 10)$q$,
        $q$SELECT tridb_sem_batch(1, 0.5, 0, 10)$q$,
        $q$SELECT tridb_sem_batch(1, 0.5, 5, 4)$q$
    ];
BEGIN
    FOREACH stmt IN ARRAY stmts LOOP
        BEGIN
            EXECUTE stmt;
            RAISE EXCEPTION 'expected an error from: %', stmt;
        EXCEPTION
            WHEN invalid_parameter_value OR null_value_not_allowed
                 OR array_subscript_error THEN NULL;
        END;
    END LOOP;
    RAISE NOTICE 'PASS P4: % invalid inputs rejected', array_length(stmts, 1);
END $$;

DROP TABLE sem_grid;
DROP TABLE sem_batch_grid;
